let artifacts = input;
if (typeof artifacts === 'string') {
  try {
    artifacts = JSON.parse(artifacts);
  } catch {
    artifacts = [];
  }
}
if (!Array.isArray(artifacts)) artifacts = [];

const screens = {};
const sources = {};

for (const item of artifacts) {
  let body = item?.content;
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch {
      body = null;
    }
  }

  const fileName = body?.fileName || item?.logicalId || item?.title || 'unknown';
  const logicalId = item?.logicalId || `screenshot-${fileName}`;
  const analysis = body?.analysis;
  if (analysis && typeof analysis === 'object') {
    screens[fileName] = analysis;
    sources[fileName] = logicalId;
  }
}

const fileNames = Object.keys(screens).sort();

return {
  screens,
  sources,
  screenCount: fileNames.length,
  fileNames,
  payloadJson: JSON.stringify({ screens, sources }, null, 2),
};

