config.code:
const slugify = (value) => String(value || 'feature').toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'feature';

let features = input;
if (typeof features === 'string') {
  try {
    features = JSON.parse(features);
  } catch {
    features = [];
  }
}
if (!Array.isArray(features)) features = [];

const used = new Set();

return features.map((feature, index) => {
  const keyword = slugify(feature?.keyword || feature?.title || `feature-${index + 1}`);
  let logicalId = `feature-${keyword}`;
  if (used.has(logicalId)) logicalId = `${logicalId}-${index + 1}`;
  used.add(logicalId);

  const category = slugify(feature?.category || 'product-features');

  return {
    title: feature?.title || `Feature ${index + 1}`,
    description: feature?.description || '',
    sourceArtifacts: Array.isArray(feature?.sourceArtifacts) ? feature.sourceArtifacts : [],
    keyword,
    category,
    logicalId,
    tags: `feature,prd,${keyword},${category},screenshots,product`,
  };
});

const prd = input && typeof input === 'object' ? input : {};
const productName = prd.productName || 'Product Features PRD';
const introduction = prd.introduction || '';
const features = Array.isArray(prd.features) ? prd.features : [];

const lines = [
  `# ${productName}`,
  '',
  introduction,
  '',
  '## Features',
  '',
];

for (const feature of features) {
  const title = feature?.title || 'Untitled feature';
  const description = feature?.description || '';
  const keyword = feature?.keyword || '';
  const category = feature?.category || '';
  const sources = Array.isArray(feature?.sourceArtifacts) ? feature.sourceArtifacts : [];
  lines.push(`### ${title}`);
  lines.push('');
  if (keyword || category) {
    lines.push(`_${[keyword && `keyword: ${keyword}`, category && `category: ${category}`].filter(Boolean).join(' · ')}_`);
    lines.push('');
  }
  lines.push(description);
  lines.push('');
  lines.push(`**Source artifacts:** ${sources.length ? sources.join(', ') : 'none cited'}`);
  lines.push('');
}

const document = {
  productName,
  introduction,
  featureCount: features.length,
  features,
  markdown: lines.join('\n'),
};

return document;

